_nc2, u.__sum_2 as __ns2 ), nv as (select up.*, __nf.__nf0, __nf.__nf1, __nf.__nf2 from up cross join lateral (select ("__trellis_a0")::bigint as __nf0, ("__trellis_a1")::numeric as __nf1, ("__trellis_a2")::bigint as __nf2 from (select up.__nn as "__trellis_a0", case when up.__nc1 = 0 then null else ((case when up.__nk1 is null then round(up.__ns1, 2) when coalesce(((up.__nk1) ->> 'NaN')::bigint, 0) > 0 or (coalesce(((up.__nk1) ->> 'Infinity')::bigint, 0) > 0 and coalesce(((up.__nk1) ->> '-Infinity')::bigint, 0) > 0) then 'NaN'::numeric when coalesce(((up.__nk1) ->> 'Infinity')::bigint, 0) > 0 then 'Infinity'::numeric when coalesce(((up.__nk1) ->> '-Infinity')::bigint, 0) > 0 then '-Infinity'::numeric else round(up.__ns1, coalesce(greatest(case when (up.__nc1) > (select coalesce(sum(value::bigint), 0) from jsonb_each_text(up.__nk1)) then 2 end, (select max(key::int) from jsonb_each_text(up.__nk1) where key not in ('NaN', 'Infinity', '-Infinity') and value::bigint > 0)), 2)) end))::numeric end as "__trellis_a1", case when up.__nc2 = 0 then null else (up.__ns2)::bigint end as "__trellis_a2") as a) as __nf), cur as ( select nv.*, t.* , (nv.__nn > 0) is distinct from (t.__tc is not null) or (nv.__nn > 0 and not ((nv.__nf0, nv.__nf1, scale(nv.__nf1), nv.__nf2) is not distinct from (t.__vf0, t.__vf1, scale(t.__vf1), t.__vf2))) as __changed from nv left join lateral (select x.ctid, x."n", x."total_score", x."total_likes" from "public"."hi_totals" x where x."grp_hi" = nv."grp_hi" union all select x.ctid, x."n", x."total_score", x."total_likes" from "public"."hi_totals" x where (nv."grp_hi" is null) and x."grp_hi" is null limit 1) as t(__tc, __vf0, __vf1, __vf2) on true ), written as ( insert into "public"."hi_totals" ("grp_hi", "n", "total_score", "total_likes") select "grp_hi", __nf0, __nf1, __nf2 from cur where __changed and __nn > 0 order by "grp_hi" on conflict ("grp_hi") do update set "n" = excluded."n", "total_score" = excluded."total_score", "total_likes" = excluded."total_likes" ), deleted as ( delete from "public"."hi_totals" where ctid = any(array( select __tc from cur where __changed and __nn <= 0 and __tc is not null)) ) select coalesce(replace(cur."grp_hi"::text, chr(1), chr(1) || chr(1)), chr(1)), cur.__changed, cur.__nn > 0, cur.__tc is not null, null::text, cur.__nn, cur.__nc1, cur.__ns1::text, cur.__nc2, cur.__ns2::text from cur;
